{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C32"],
      "claim": "Linezolid, the closest analogue sharing the oxazolidinone core and para-aminophenyl substituent, has essentially complete (100%) absolute oral bioavailability in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Delpazolid, another oxazolidinone with a para-aminophenyl group, showed 99.75% absolute oral bioavailability after an 800 mg oral dose in healthy subjects.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Contezolid, a structurally related oxazolidinone, had an absolute bioavailability of 0.64 in healthy subjects, still well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "YH4808, a close oxazolidinone analogue containing a thiomorpholine ring, had low absolute bioavailability (10.1%); this contradictory result is unlikely to transfer because the query lacks the thiomorpholine sulfur and instead contains a morpholinone ring.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F >= 20%): the query is a linezolid-like oxazolidinone, and the closest high-bioavailability analogues (linezolid, delpazolid, contezolid) support F >= 20%. The closest low-F analogue, YH4808, has a thiomorpholine moiety not present in the query, limiting its transferability.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement exists for the query molecule.",
    "The combined effect of replacing linezolid's morpholine with morpholin-3-one and acetyl with 5-chlorothiophene carboxamide on human oral bioavailability is not directly evidenced.",
    "The mechanism underlying YH4808's low bioavailability is not detailed in the record, so a core-related first-pass liability cannot be fully excluded."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

